"use client";

import { useCallback } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { api, ApiError } from "@workpal/core/api";
import { useWorkspaceId } from "@workpal/core/hooks";
import { chatKeys } from "@workpal/core/chat/queries";
import {
  prioritizePendingChatTask,
  removePendingChatTask,
} from "@workpal/core/chat/pending";
import { removeChatMessageFromCaches } from "@workpal/core/realtime";
import { createLogger } from "@workpal/core/logger";
import type {
  Attachment,
  CancelTaskResponse,
  ChatPendingTask,
} from "@workpal/core/types";
import { useT } from "../../i18n";

const apiLogger = createLogger("chat.api");

type EnqueueLocalRestore = (restore: {
  id: string;
  content: string;
  attachments?: Attachment[];
  sessionId: string;
}) => void;

type CancelOptions = {
  restoreDraftToInput: boolean;
  source: string;
  queuedAction?: "edit" | "remove";
};

export function useChatTaskActions(
  activeSessionId: string | null,
  enqueueLocalRestore: EnqueueLocalRestore,
) {
  const { t } = useT("chat");
  const wsId = useWorkspaceId();
  const qc = useQueryClient();

  const cancelChatTask = useCallback(
    async (
      taskId: string,
      sessionId: string,
      options: CancelOptions,
    ): Promise<CancelTaskResponse | null> => {
      apiLogger.info("cancelTask.start", {
        taskId,
        sessionId,
        source: options.source,
      });
      const pendingKey = chatKeys.pendingTask(sessionId);
      await qc.cancelQueries({ queryKey: pendingKey });
      const pendingSnapshot = qc.getQueryData<ChatPendingTask>(pendingKey);
      const derivedQueuedAction = !options.queuedAction &&
        (options.restoreDraftToInput &&
            pendingSnapshot?.task_id === taskId &&
            pendingSnapshot.status === "queued" &&
            pendingSnapshot.supports_queue === true);
      let queuedAction = options.queuedAction ??
        (derivedQueuedAction ? "edit" : undefined);
      qc.setQueryData<ChatPendingTask>(
        pendingKey,
        (old) => removePendingChatTask(old, taskId),
      );

      try {
        let result: CancelTaskResponse;
        try {
          result = await api.cancelTaskById(
            taskId,
            queuedAction ? { queuedAction, sessionId } : undefined,
          );
        } catch (err) {
          if (!(derivedQueuedAction && err instanceof ApiError && err.status === 409)) {
            throw err;
          }
          // The daemon claimed the task after our cached queued snapshot.
          // Preserve Stop semantics by cancelling its new active state.
          queuedAction = undefined;
          result = await api.cancelTaskById(taskId);
        }
        const restored = result.cancelled_chat_message;
        if (restored) {
          removeChatMessageFromCaches(qc, restored.chat_session_id, restored.message_id);
          if (
            restored.restore_to_input &&
            !queuedAction &&
            options.restoreDraftToInput &&
            restored.chat_session_id === sessionId
          ) {
            enqueueLocalRestore({
              id: restored.message_id,
              content: restored.content,
              attachments: restored.attachments,
              sessionId: restored.chat_session_id,
            });
          }
        }
        qc.invalidateQueries({ queryKey: chatKeys.messages(sessionId) });
        qc.invalidateQueries({ queryKey: chatKeys.messagesPage(sessionId) });
        apiLogger.info("cancelTask.success", {
          taskId,
          sessionId,
          restoredToInput: !!restored?.restore_to_input && options.restoreDraftToInput,
        });
        return result;
      } catch (err) {
        qc.setQueryData(pendingKey, pendingSnapshot);
        apiLogger.warn("cancelTask.error (task may have already finished)", {
          taskId,
          sessionId,
          err,
        });
        qc.invalidateQueries({ queryKey: chatKeys.messages(sessionId) });
        qc.invalidateQueries({ queryKey: chatKeys.messagesPage(sessionId) });
        return null;
      } finally {
        qc.invalidateQueries({ queryKey: pendingKey });
        if (queuedAction === "edit") {
          qc.invalidateQueries({ queryKey: chatKeys.draftRestores(sessionId) });
        }
        if (wsId) qc.invalidateQueries({ queryKey: chatKeys.pendingTasks(wsId) });
      }
    },
    [qc, enqueueLocalRestore, wsId],
  );

  const handleEditQueuedTask = useCallback(
    async (taskId: string) => {
      if (!activeSessionId) return;
      const result = await cancelChatTask(taskId, activeSessionId, {
        restoreDraftToInput: true,
        source: "queued-message-edit",
        queuedAction: "edit",
      });
      if (!result) toast.error(t(($) => $.queue.action_failed_toast));
    },
    [activeSessionId, cancelChatTask, t],
  );

  const handleRemoveQueuedTask = useCallback(
    async (taskId: string) => {
      if (!activeSessionId) return;
      const result = await cancelChatTask(taskId, activeSessionId, {
        restoreDraftToInput: false,
        source: "queued-message-remove",
        queuedAction: "remove",
      });
      if (!result) toast.error(t(($) => $.queue.action_failed_toast));
    },
    [activeSessionId, cancelChatTask, t],
  );

  const handleClearQueuedTasks = useCallback(async () => {
    if (!activeSessionId) return;
    const pendingKey = chatKeys.pendingTask(activeSessionId);
    await qc.cancelQueries({ queryKey: pendingKey });
    try {
      await api.clearQueuedChatTasks(activeSessionId);
      const pending = qc.getQueryData<ChatPendingTask>(pendingKey);
      for (const task of pending?.queued_tasks ?? []) {
        if (task.message_id) {
          removeChatMessageFromCaches(qc, activeSessionId, task.message_id);
        }
      }
      qc.setQueryData<ChatPendingTask>(pendingKey, (old) =>
        (old?.queued_tasks ?? []).reduce<ChatPendingTask | undefined>(
          (current, task) => removePendingChatTask(current, task.task_id),
          old,
        )
      );
    } catch (err) {
      apiLogger.warn("clearQueuedTasks.error", {
        sessionId: activeSessionId,
        err,
      });
      toast.error(t(($) => $.queue.action_failed_toast));
    } finally {
      qc.invalidateQueries({ queryKey: pendingKey });
      qc.invalidateQueries({ queryKey: chatKeys.messages(activeSessionId) });
      qc.invalidateQueries({ queryKey: chatKeys.messagesPage(activeSessionId) });
      if (wsId) qc.invalidateQueries({ queryKey: chatKeys.pendingTasks(wsId) });
    }
  }, [activeSessionId, qc, t, wsId]);

  const handleSendQueuedTaskNow = useCallback(
    async (taskId: string) => {
      if (!activeSessionId) return;
      const pendingKey = chatKeys.pendingTask(activeSessionId);
      await qc.cancelQueries({ queryKey: pendingKey });
      const pendingSnapshot = qc.getQueryData<ChatPendingTask>(pendingKey);
      qc.setQueryData<ChatPendingTask>(
        pendingKey,
        (old) => prioritizePendingChatTask(old, taskId),
      );
      let prioritizeSucceeded = false;
      try {
        const result = await api.prioritizeQueuedChatTask(activeSessionId, taskId);
        if (result.task_id !== taskId) throw new Error("invalid prioritize response");
        prioritizeSucceeded = true;
        if (result.active_task_id) {
          const cancelled = await cancelChatTask(result.active_task_id, activeSessionId, {
            restoreDraftToInput: true,
            source: "queued-message-send-now",
          });
          if (!cancelled) throw new Error("current task could not be stopped");
        }
      } catch (err) {
        if (!prioritizeSucceeded) qc.setQueryData(pendingKey, pendingSnapshot);
        apiLogger.warn("sendQueuedTaskNow.error", {
          taskId,
          sessionId: activeSessionId,
          err,
        });
        toast.error(
          err instanceof ApiError && err.status === 409
            ? t(($) => $.queue.steer_unavailable_toast)
            : t(($) => $.queue.action_failed_toast),
        );
      } finally {
        qc.invalidateQueries({ queryKey: pendingKey });
      }
    },
    [activeSessionId, cancelChatTask, qc, t],
  );

  return {
    cancelChatTask,
    handleEditQueuedTask,
    handleRemoveQueuedTask,
    handleClearQueuedTasks,
    handleSendQueuedTaskNow,
  };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  useInfiniteQuery,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";
import { toast } from "sonner";
import { useWorkspaceId } from "@workpal/core/hooks";
import { useAuthStore } from "@workpal/core/auth";
import { getCurrentWsId } from "@workpal/core/platform";
import { agentListOptions, memberListOptions } from "@workpal/core/workspace/queries";
import { projectListOptions } from "@workpal/core/projects/queries";
import { canAssignAgent } from "../../issues/components/pickers/assignee-picker";
import { api, dispatchReasonCode } from "@workpal/core/api";
import {
  isAgentRuntimeBound as hasAgentRuntime,
  useAgentPresenceDetail,
  useWorkspaceAgentAvailability,
} from "@workpal/core/agents";
import {
  chatSessionsOptions,
  chatMessagesPageOptions,
  pendingChatTaskOptions,
  chatKeys,
  isTaskMessageTaskId,
  sortChatSessions,
} from "@workpal/core/chat/queries";
import {
  useCreateChatSession,
  useMarkChatSessionRead,
  useSetChatSessionProject,
  useSetChatSessionArchived,
} from "@workpal/core/chat/mutations";
import { useChatStore } from "@workpal/core/chat";
import { upsertChatMessageToCaches } from "@workpal/core/chat/message-cache";
import { refetchChatSessionsAfterCommit } from "@workpal/core/chat/session-list";
import {
  enqueuePendingChatTask,
  hideQueuedChatMessages,
} from "@workpal/core/chat/pending";
import { useChatDraftRestore } from "./use-chat-draft-restore";
import { useChatTaskActions } from "./use-chat-task-actions";
import { useChatProjectContextSupport } from "./use-chat-project-context-support";
import { createLogger } from "@workpal/core/logger";
import type {
  Agent,
  Attachment,
  ChatMessage,
  ChatPendingTask,
} from "@workpal/core/types";
import { useT } from "../../i18n";
import { useAppForeground } from "../../common/use-app-foreground";

const uiLogger = createLogger("chat.ui");
const apiLogger = createLogger("chat.api");

/**
 * After a send resolves: is the user still composing to the target they sent
 * from? Decides whether to scrub the composer and open the sent session, or
 * treat the send as fire-and-forget (the reply surfaces as unread instead).
 *
 * The active session answers this on its own, deliberately. The new-chat
 * composer is ONE box per workspace (see DRAFT_NEW_SESSION), so moving the
 * agent picker re-points where the next send goes without moving the view or
 * the draft slot — that is not "navigating away" (MUL-4864). Counting it as
 * such would leave a completed send's text sitting in the composer, primed to
 * be sent a second time to the agent just picked.
 */
export function isStillOnComposeTarget(
  liveActiveSessionId: string | null,
  sentFromSessionId: string | null,
): boolean {
  return liveActiveSessionId === sentFromSessionId;
}

/**
 * Decide what a project-context change should do, given the open session.
 *
 *  - `awaitSession`: an active session id is set but its row has not loaded
 *    yet. Bail so a persisted selection resolving before its sessions query
 *    cannot misfile a project change into the new-chat draft.
 *  - `detachCurrent`: removing context from the open session — safe in place,
 *    it only changes what future turns receive.
 *  - `startFreshChat`: switching to a DIFFERENT project. A fresh chat is
 *    started so the old project's provider memory / reused workdir cannot
 *    bleed in. It must stay bound to the agent whose session we are leaving
 *    (`agentId`): clearing the active session otherwise drops selection back
 *    to the stored `selectedAgentId`, which can be a stale preference for a
 *    different agent, sending the lazily-created session to the wrong agent.
 *  - `setDraftProject`: no open session, so this only adjusts the new-chat
 *    draft's project.
 */
export type ProjectContextChange =
  | { kind: "awaitSession" }
  | { kind: "detachCurrent"; sessionId: string }
  | { kind: "startFreshChat"; agentId: string; projectId: string }
  | { kind: "setDraftProject"; projectId: string | null };

export function planProjectContextChange(input: {
  targetProjectId: string | null;
  activeSessionId: string | null;
  currentSession: { id: string; agent_id: string } | null;
}): ProjectContextChange {
  if (input.activeSessionId) {
    if (!input.currentSession) return { kind: "awaitSession" };
    if (input.targetProjectId === null) {
      return { kind: "detachCurrent", sessionId: input.currentSession.id };
    }
    return {
      kind: "startFreshChat",
      agentId: input.currentSession.agent_id,
      projectId: input.targetProjectId,
    };
  }
  return { kind: "setDraftProject", projectId: input.targetProjectId };
}

// True when a session has an in-flight pending task in the cache — the signal
// of a just-created (or actively-sending) session still awaiting server
// confirmation, before the sessions-list refetch includes it. `handleSend`
// seeds this task from the server response the instant the send is accepted, so
// it is populated before `setActiveSession` publishes the new session.
// Deliberately NOT "has cached messages": a session deleted elsewhere can still
// have real cached history, which must not exempt it from the stale-session
// self-heal.
export function hasInFlightPendingTask(
  qc: ReturnType<typeof useQueryClient>,
  sessionId: string,
): boolean {
  const pending = qc.getQueryData<ChatPendingTask>(chatKeys.pendingTask(sessionId));
  return Boolean(pending?.task_id);
}

export function seedAcceptedPendingTask(
  qc: ReturnType<typeof useQueryClient>,
  sessionId: string,
  task: {
    task_id: string;
    created_at: string;
    message_id: string;
    content: string;
    supports_queue?: boolean;
    queued?: boolean;
  },
) {
  qc.setQueryData<ChatPendingTask>(
    chatKeys.pendingTask(sessionId),
    (old) => {
      const next = enqueuePendingChatTask(old, {
        task_id: task.task_id,
        status: "queued",
        created_at: task.created_at,
        message_id: task.message_id,
        content: task.content,
      }, task.queued);
      if (task.supports_queue === true || old?.supports_queue === true) {
        next.supports_queue = true;
      }
      return next;
    },
  );
  qc.invalidateQueries({ queryKey: chatKeys.pendingTask(sessionId) });
}

const CHAT_VIRTUOSO_INITIAL_FIRST_ITEM_INDEX = 1_000_000;


/**
 * Layout-agnostic chat controller. Holds every piece of chat conversation
 * state and behavior — agent resolution, session lookup, the await-then-render
 * send/stop/cancel flow, message pagination, and auto-mark-read — so that
 * both surfaces render the same conversation logic:
 *
 *  - ChatWindow: the floating FAB overlay (adds resize / expand / minimize).
 *  - ChatPage:   the first-class Chat tab (two-pane thread list + conversation).
 *
 * The only thing the caller supplies is `isActive` — whether its surface is
 * currently on screen — which gates auto-mark-read so a background overlay
 * doesn't silently clear unread state the user hasn't actually seen.
 */
export function useChatController(opts?: { isActive?: boolean }) {
  const isActive = opts?.isActive ?? true;
  const { t } = useT("chat");
  const wsId = useWorkspaceId();
  const activeSessionId = useChatStore((s) => s.activeSessionId);
  const selectedAgentId = useChatStore((s) => s.selectedAgentId);
  const selectedProjectId = useChatStore((s) => s.selectedProjectId);
  const setActiveSession = useChatStore((s) => s.setActiveSession);
  const setSelectedAgentId = useChatStore((s) => s.setSelectedAgentId);
  const setSelectedProjectId = useChatStore((s) => s.setSelectedProjectId);
  const user = useAuthStore((s) => s.user);
  const { data: agents = [], isSuccess: agentsLoaded } = useQuery(
    agentListOptions(wsId),
  );
  const { data: members = [], isSuccess: membersLoaded } = useQuery(
    memberListOptions(wsId),
  );
  const { data: sessions = [], isSuccess: sessionsLoaded } = useQuery(
    chatSessionsOptions(wsId),
  );
  const { data: projects = [], isSuccess: projectsLoaded } = useQuery(
    projectListOptions(wsId),
  );
  const {
    data: rawMessagePages,
    isLoading: messagesLoading,
    fetchNextPage: fetchOlderMessages,
    hasNextPage: hasOlderMessages,
    isFetchingNextPage: isFetchingOlderMessages,
  } = useInfiniteQuery({
    ...chatMessagesPageOptions(activeSessionId ?? ""),
    // The floating window stays mounted while closed; it must not load a
    // persisted session's transcript nobody is looking at.
    enabled: !!activeSessionId && isActive,
  });

  const messagePages = activeSessionId ? rawMessagePages?.pages ?? [] : [];
  const allMessages = [...messagePages].reverse().flatMap((page) => page.messages);

  const { data: pendingTask, isLoading: pendingTaskLoading } = useQuery(
    pendingChatTaskOptions(activeSessionId ?? ""),
  );
  const showSkeleton =
    !!activeSessionId && (messagesLoading || pendingTaskLoading);
  const messages = hideQueuedChatMessages(allMessages, pendingTask);
  const olderMessageCount = messagePages
    .slice(1)
    .reduce((sum, page) => sum + page.messages.length, 0);
  const firstItemIndex =
    messages.length > 0
      ? CHAT_VIRTUOSO_INITIAL_FIRST_ITEM_INDEX - olderMessageCount
      : 0;
  const pendingTaskId = pendingTask?.task_id ?? null;
  const stopRequestedBeforeTaskRef = useRef(false);
  // Durable deferred-cancellation draft restores (#5219). The whole lifecycle —
  // fetch, offer, skip-and-re-offer, apply, consume, reconcile — lives in this
  // hook, shared with the floating chat window.
  //
  // Gated on isActive AND app foreground: a backgrounded browser tab still renders
  // this controller, and it must not fetch/apply/consume a restore the user is
  // waiting on in a foreground surface. It recovers on its next fetch once the
  // surface is on screen and the app is refocused. (appForeground also gates auto
  // mark-read below.)
  const appForeground = useAppForeground();
  const { restoreDraftRequest, enqueueLocalRestore, handleRestoreDraftApplied } =
    useChatDraftRestore(activeSessionId, isActive && appForeground);
  const {
    cancelChatTask,
    handleEditQueuedTask,
    handleRemoveQueuedTask,
    handleClearQueuedTasks,
    handleSendQueuedTaskNow,
  } = useChatTaskActions(activeSessionId, enqueueLocalRestore);
  // Nonce handed to ChatInput to pull focus into the compose box when a new
  // chat starts (new chat, agent switch, project change, conversation
  // starter), so selecting an existing chat or a deep link never steals focus.
  const [focusInputRequest, setFocusInputRequest] = useState(0);
  const requestInputFocus = useCallback(
    () => setFocusInputRequest((n) => n + 1),
    [],
  );
  const [conversationStarterRequest, setConversationStarterRequest] = useState<{
    id: number;
    content: string;
  } | null>(null);
  const nextConversationStarterRequestIdRef = useRef(0);
  const sendConversationStarter = useCallback(
    (prompt: string) => {
      setConversationStarterRequest({
        id: ++nextConversationStarterRequestIdRef.current,
        content: prompt,
      });
      requestInputFocus();
    },
    [requestInputFocus],
  );
  const handleConversationStarterApplied = useCallback(
    () => setConversationStarterRequest(null),
    [],
  );

  const currentSession = activeSessionId
    ? sessions.find((s) => s.id === activeSessionId)
    : null;
  const isSessionArchived = currentSession?.status === "archived";
  const candidateProjectId = currentSession
    ? currentSession.project_id ?? null
    : selectedProjectId;
  const activeProjectId = candidateProjectId &&
    (!projectsLoaded || projects.some((project) => project.id === candidateProjectId))
    ? candidateProjectId
    : null;

  // A project may be deleted on another client while this workspace's next
  // chat preference is still persisted locally. Normalize it as soon as the
  // authoritative project list settles so a future send cannot carry a stale
  // selection. An outgoing route can retain its queries after the shared
  // store has rehydrated another workspace; only clean up our own namespace.
  useEffect(() => {
    if (getCurrentWsId() !== wsId) return;
    if (!projectsLoaded || !selectedProjectId) return;
    if (projects.some((project) => project.id === selectedProjectId)) return;
    setSelectedProjectId(null);
  }, [wsId, projectsLoaded, projects, selectedProjectId, setSelectedProjectId]);

  const qc = useQueryClient();
  const createSession = useCreateChatSession();
  const markRead = useMarkChatSessionRead();
  const setSessionProject = useSetChatSessionProject();
  const setArchived = useSetChatSessionArchived();

  const currentMember = members.find((m) => m.user_id === user?.id);
  const memberRole = currentMember?.role;
  const availableAgents = agents.filter(
    (a) => !a.archived_at && canAssignAgent(a, user?.id, memberRole),
  );
  // `availableAgents` is only trustworthy once BOTH queries above succeeded:
  // the permission filter reads the member role, so agents-without-members
  // misreports a public_to agent as unavailable. Consumers that must tell
  // "still loading" apart from "settled and not available" (the `?agent=`
  // deep link) gate on this instead of sniffing list emptiness. Query errors
  // deliberately keep this false — a failed fetch is not a permission verdict.
  const agentsSettled = agentsLoaded && membersLoaded;

  // The agent bound to the OPEN session, resolved from the full agent list
  // (archived included, since agentListOptions passes include_archived). An
  // archived agent is filtered out of `availableAgents`, so resolving the
  // active agent only from that list would make an archived-agent session
  // silently render some *other* available agent — wrong avatar/name/presence
  // in the header, and a send that targets the wrong agent. Binding to the
  // session's real agent keeps the conversation honest; the archived state
  // then makes it read-only (see isAgentArchived).
  const sessionAgent = currentSession
    ? agents.find((a) => a.id === currentSession.agent_id) ?? null
    : null;
  const isAgentArchived = !!sessionAgent?.archived_at;

  // Resolve selected agent: open session's agent → stored preference → first
  // available. New chats have no session, so they fall through to the picker.
  const activeAgent =
    sessionAgent ??
    availableAgents.find((a) => a.id === selectedAgentId) ??
    availableAgents[0] ??
    null;
  const isAgentRuntimeBound = !!activeAgent && hasAgentRuntime(activeAgent);

  // A session outlives the permission that created it. The agent can be flipped
  // to personal, change owner, or drop this member from its allow-list, and the
  // server then refuses every send with `invocation_not_allowed` while still
  // serving the transcript (MUL-4525 — read uses the view gate, send re-runs the
  // invoke gate). Judge the SESSION's agent, not just the picker list, so the
  // composer goes read-only up front instead of after the user types
  // (MUL-6380). Same rule the server enforces, via the shared predicate.
  const isAgentAccessRevoked =
    !!activeAgent && !canAssignAgent(activeAgent, user?.id, memberRole);

  const agentAvailability = useWorkspaceAgentAvailability();
  const noAgent = agentAvailability === "none";

  const projectContextSupport = useChatProjectContextSupport(wsId, activeAgent);

  const presenceDetail = useAgentPresenceDetail(wsId, activeAgent?.id);
  const availability =
    presenceDetail === "loading" ? undefined : presenceDetail.availability;

  // Auto mark-as-read whenever the user is actively looking at a session with
  // unread state. `isActive` lets the caller say "my surface is on screen":
  // the floating overlay passes `isOpen`, the tab passes `true`. `appForeground`
  // additionally requires the window to be visible and focused: a reply landing
  // while the app is backgrounded must stay unread so the sidebar badges it
  // (MUL-4485); it clears the moment the user returns and this effect re-runs.
  //
  // The read is deferred by a tick and cancelled on cleanup, so a session that
  // is only *momentarily* active never gets marked read. This is the fix for
  // MUL-4360's mount race: `activeSessionId` is persisted, so on a bare `/chat`
  // navigation the page restores the last session for one frame before its
  // URL→store effect (which runs AFTER this hook's effects, since the hook is
  // called first) clears it back to null. Without the defer, that restored-but-
  // never-opened session was marked read in that gap — its badge vanished
  // though the user never opened it (right pane still shows "select a chat").
  // Deferring lets the subsequent activeSessionId change cancel the pending
  // read via cleanup; the store re-check is a belt-and-suspenders guard. Only a
  // session that stays active past the tick — a real select, deep link, or
  // refresh — is read.
  const currentHasUnread =
    sessions.find((s) => s.id === activeSessionId)?.has_unread ?? false;
  useEffect(() => {
    if (!isActive || !appForeground || !activeSessionId) return;
    if (!currentHasUnread) return;
    const sessionId = activeSessionId;
    const timer = setTimeout(() => {
      if (useChatStore.getState().activeSessionId !== sessionId) return;
      uiLogger.info("auto markRead", { sessionId });
      markRead.mutate(sessionId);
    }, 0);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- markRead ref stable
  }, [isActive, appForeground, activeSessionId, currentHasUnread]);

  const sessionPromiseRef = useRef<Promise<string | null> | null>(null);
  const ensureSession = useCallback(
    async (): Promise<string | null> => {
      // Trust the current session id only when it's real: present in the
      // loaded list, or a just-created one still awaiting the list refetch
      // (has an optimistic write). A dangling id (deleted / no access) must not
      // be treated as an existing session — fall through and create a fresh one
      // so the message lands somewhere instead of POSTing into a 404.
      if (
        activeSessionId &&
        (!sessionsLoaded ||
          sessions.some((s) => s.id === activeSessionId) ||
          hasInFlightPendingTask(qc, activeSessionId))
      ) {
        return activeSessionId;
      }
      if (!activeAgent) return null;
      if (sessionPromiseRef.current) return sessionPromiseRef.current;

      const promise = (async () => {
        try {
          // Untitled on purpose: the server derives the title from the first
          // message it accepts, the same rule for every client and channel.
          const session = await createSession.mutateAsync({
            agent_id: activeAgent.id,
            project_id: activeProjectId,
          });
          return session.id;
        } finally {
          sessionPromiseRef.current = null;
        }
      })();
      sessionPromiseRef.current = promise;
      return promise;
    },
    [
      activeSessionId,
      activeAgent,
      activeProjectId,
      createSession,
      sessions,
      sessionsLoaded,
      qc,
    ],
  );

  // Self-heal a dangling `activeSessionId`. Once the sessions list has loaded
  // and it isn't in the list — with no in-flight optimistic write exempting a
  // just-created session — the id was deleted, lost access, or never existed
  // (a stale `?session=` deep link, or a persisted floating-window selection).
  // Clearing it stops BOTH surfaces (the tab and the floating window) from
  // rendering an editable empty chat whose send would POST into a nonexistent
  // session. Lives in the shared controller so every surface self-heals.
  useEffect(() => {
    if (getCurrentWsId() !== wsId) return;
    if (!activeSessionId || !sessionsLoaded) return;
    if (sessions.some((s) => s.id === activeSessionId)) return;
    if (hasInFlightPendingTask(qc, activeSessionId)) return;
    uiLogger.info("clearing dangling activeSessionId", { sessionId: activeSessionId });
    setActiveSession(null);
  }, [wsId, activeSessionId, sessionsLoaded, sessions, qc, setActiveSession]);

  // Upload transport moved into the coordinated-upload engine inside ChatInput
  // (MUL-5181 L2); surfaces only forward whether the affordance exists.
  const uploadEnabled = !!activeAgent;

  const handleSend = useCallback(
    async (
      content: string,
      attachmentIds?: string[],
      commitInput?: (options?: { extraDraftKeys?: string[]; clearEditor?: boolean }) => void,
      draftAttachments: Attachment[] = [],
      options?: { queue?: boolean },
    ): Promise<boolean> => {
      if (!activeAgent) {
        apiLogger.warn("sendChatMessage skipped: no active agent");
        return false;
      }
      // Read-only conversation: the agent is retired and can no longer pick up
      // work, so refuse to enqueue a task that would sit orphaned forever. The
      // input is disabled in this state; this is the belt-and-braces guard.
      if (isAgentArchived) {
        apiLogger.warn("sendChatMessage skipped: agent is archived", {
          sessionId: activeSessionId,
          agentId: activeAgent.id,
        });
        return false;
      }
      // Invoke permission was revoked while this session was open. The server
      // would refuse with a 403 before persisting anything; not attempting the
      // send keeps the draft and avoids a pointless roundtrip. The input is
      // disabled in this state — this is the belt-and-braces guard.
      if (isAgentAccessRevoked) {
        apiLogger.warn("sendChatMessage skipped: invoke permission revoked", {
          sessionId: activeSessionId,
          agentId: activeAgent.id,
        });
        return false;
      }
      if (pendingTaskId && pendingTask?.supports_queue !== true) {
        apiLogger.warn("sendChatMessage skipped: server does not support follow-up queues", {
          sessionId: activeSessionId,
        });
        return false;
      }
      if (!isAgentRuntimeBound) {
        toast.error(t(($) => $.input.runtime_required_toast));
        return false;
      }

      const finalContent = content;
      const isNewSession = !activeSessionId;

      apiLogger.info("sendChatMessage.start", {
        sessionId: activeSessionId,
        isNewSession,
        agentId: activeAgent.id,
        contentLength: finalContent.length,
        attachmentCount: attachmentIds?.length ?? 0,
      });

      let sessionId: string | null = null;
      try {
        sessionId = await ensureSession();
      } catch (err) {
        apiLogger.error("sendChatMessage.ensureSession.error", err);
        // A revoked invoke permission blocks session create with a structured
        // 403 (MUL-4525) — name the cause instead of a generic failure.
        const reason = dispatchReasonCode(err);
        toast.error(
          reason === "invocation_not_allowed"
            ? t(($) => $.input.send_blocked_toast)
            : reason === "agent_runtime_required"
              ? t(($) => $.input.runtime_required_toast)
              : reason === "runtime_access_denied"
                ? t(($) => $.input.runtime_access_denied_toast)
                : t(($) => $.input.send_failed_toast),
        );
        return false;
      }
      if (!sessionId) {
        apiLogger.warn("sendChatMessage aborted: ensureSession returned null");
        return false;
      }

      // Await-then-render: the composer keeps the user's text and attachments
      // in place (editor locked, button spinning via `submitting`) until the
      // server accepts the send. Nothing is written into the caches, and the
      // draft is never cleared, before the roundtrip settles — a slow send never
      // reads as "posted but the box is still full", and a rejected one keeps
      // the draft for retry (ChatInput never cleared it).
      let result;
      try {
        result = options?.queue
          ? await api.sendChatMessage(sessionId, finalContent, attachmentIds, options)
          : await api.sendChatMessage(sessionId, finalContent, attachmentIds);
      } catch (err) {
        apiLogger.error("sendChatMessage.error", { sessionId, err });
        // Invoke permission can be revoked mid-session; the send is refused with
        // a structured 403 before anything persists (MUL-4525). Surface the
        // specific cause so the user knows it is a permission change, not a
        // transient failure they should retry.
        const reason = dispatchReasonCode(err);
        toast.error(
          reason === "invocation_not_allowed"
            ? t(($) => $.input.send_blocked_toast)
            : reason === "agent_runtime_required"
              ? t(($) => $.input.runtime_required_toast)
              : reason === "runtime_access_denied"
                ? t(($) => $.input.runtime_access_denied_toast)
                : t(($) => $.input.send_failed_toast),
        );
        return false;
      }
      apiLogger.info("sendChatMessage.success", {
        sessionId,
        messageId: result.message_id,
        taskId: result.task_id,
      });

      // Render the accepted message from the server response. Prime the message
      // caches BEFORE publishing the session so the first useQuery read after
      // activeSessionId flips hits data synchronously (no new-chat skeleton
      // flash), and seed the pending task with the server's real id and
      // created_at so the StatusPill mounts anchored to the true clock and the
      // stale-session self-heal exempts this just-created session until the
      // sessions-list refetch includes it.
      const sent: ChatMessage = {
        id: result.message_id,
        chat_session_id: sessionId,
        role: "user",
        content: finalContent,
        task_id: result.message_task_id ?? result.task_id,
        created_at: result.message_created_at ?? result.created_at,
        attachments: draftAttachments,
      };
      // Single door into the message caches (MUL-5711): idempotent by id, so
      // this row and the chat:message echo of the same send converge in either
      // arrival order, and this richer row (it carries the draft attachments)
      // is never downgraded by the echo, which has no attachments field.
      upsertChatMessageToCaches(qc, sessionId, sent, { seedIfMissing: true });
      if (result.steered !== true) {
        seedAcceptedPendingTask(qc, sessionId, {
          task_id: result.task_id,
          created_at: result.created_at,
          message_id: result.message_id,
          content: finalContent,
          supports_queue: result.supports_queue,
          queued: result.queued,
        });
      }
      // This send just committed the new session's server-derived title.
      if (sessionId !== activeSessionId) {
        void refetchChatSessionsAfterCommit(qc, chatKeys.sessions(wsId));
      }
      // Cache primed → publish the new active session, but only if the user
      // hasn't navigated away mid-send. See isStillOnComposeTarget. commitInput
      // clears the sent draft, and scrubs the shared editor only when the user
      // is still on the session they sent from.
      const live = useChatStore.getState();
      const stillOnSourceSession = isStillOnComposeTarget(live.activeSessionId, activeSessionId);
      if (stillOnSourceSession) {
        setActiveSession(sessionId);
      }
      commitInput?.({ extraDraftKeys: [sessionId], clearEditor: stillOnSourceSession });

      if (stopRequestedBeforeTaskRef.current) {
        stopRequestedBeforeTaskRef.current = false;
        await cancelChatTask(result.task_id, sessionId, {
          restoreDraftToInput: true,
          source: "deferred-send",
        });
        return false;
      }
      if (attachmentIds && attachmentIds.length > 0 && result.attachment_ids) {
        const boundIds = new Set(result.attachment_ids);
        const missing = attachmentIds.filter((id) => !boundIds.has(id));
        if (missing.length > 0) {
          apiLogger.warn("sendChatMessage.attachments missing after send", {
            sessionId,
            messageId: result.message_id,
            missing,
          });
          toast.error(t(($) => $.input.attachment_bind_failed_toast));
        }
      }
      qc.invalidateQueries({ queryKey: chatKeys.messages(sessionId) });
      qc.invalidateQueries({ queryKey: chatKeys.messagesPage(sessionId) });
      return true;
    },
    [
      wsId,
      activeSessionId,
      activeAgent,
      isAgentArchived,
      isAgentAccessRevoked,
      pendingTask,
      pendingTaskId,
      isAgentRuntimeBound,
      ensureSession,
      cancelChatTask,
      qc,
      setActiveSession,
      t,
    ],
  );

  const handleStop = useCallback(() => {
    if (!pendingTaskId || !activeSessionId) {
      apiLogger.debug("cancelTask skipped: no pending task");
      return;
    }
    if (!isTaskMessageTaskId(pendingTaskId)) {
      stopRequestedBeforeTaskRef.current = true;
      apiLogger.info("cancelTask.deferred until server task id", {
        taskId: pendingTaskId,
        sessionId: activeSessionId,
      });
      return;
    }
    void cancelChatTask(pendingTaskId, activeSessionId, {
      restoreDraftToInput: true,
      source: "active-input",
    });
  }, [pendingTaskId, activeSessionId, cancelChatTask]);

  const handleNewChat = useCallback(() => {
    uiLogger.info("newChat", {
      previousSessionId: activeSessionId,
      previousPendingTask: pendingTaskId,
    });
    // A fresh chat has no project unless the user explicitly chooses one.
    // The open session's project is server-owned history, not a default for
    // the next session.
    setSelectedProjectId(null);
    setActiveSession(null);
    requestInputFocus();
  }, [
    activeSessionId,
    pendingTaskId,
    setSelectedProjectId,
    setActiveSession,
    requestInputFocus,
  ]);

  // Start a fresh chat bound to a chosen agent. Unlike handleSelectAgent this
  // does not no-op when the agent is unchanged — "new chat" always clears the
  // active session so the user lands on an empty compose for that agent. The
  // session row is created lazily on the first send (see ensureSession).
  const handleStartNewChat = useCallback(
    (agent: Agent) => {
      uiLogger.info("startNewChat", {
        agentId: agent.id,
        previousSessionId: activeSessionId,
      });
      setSelectedAgentId(agent.id);
      setSelectedProjectId(null);
      setActiveSession(null);
      requestInputFocus();
    },
    [
      activeSessionId,
      setSelectedAgentId,
      setSelectedProjectId,
      setActiveSession,
      requestInputFocus,
    ],
  );

  // Switch the composer to another agent (the floating window's agent picker).
  const handleSelectAgent = useCallback(
    (agent: Agent) => {
      // No-op when clicking the already-active agent — don't clobber the
      // current session just because the user closed the menu this way.
      // Compare against activeAgent (what the UI shows), not selectedAgentId
      // (which may be null / point to an archived agent on first load).
      if (activeAgent && agent.id === activeAgent.id) return;
      uiLogger.info("selectAgent", {
        from: selectedAgentId,
        to: agent.id,
        previousSessionId: activeSessionId,
      });
      setSelectedAgentId(agent.id);
      // Preserve an explicitly chosen project while composing an unsent chat,
      // but never inherit project context from the historical session being
      // left behind.
      setSelectedProjectId(currentSession ? null : activeProjectId);
      setActiveSession(null);
      requestInputFocus();
    },
    [
      activeAgent,
      selectedAgentId,
      activeSessionId,
      activeProjectId,
      currentSession,
      setSelectedAgentId,
      setSelectedProjectId,
      setActiveSession,
      requestInputFocus,
    ],
  );

  const handleSelectSession = useCallback(
    (session: { id: string; agent_id: string; project_id?: string | null }) => {
      // Sessions are bound 1:1 to an agent — picking a session from a
      // different agent implicitly switches the agent too.
      if (activeAgent && session.agent_id !== activeAgent.id) {
        uiLogger.info("selectSession (cross-agent)", {
          from: activeAgent.id,
          toAgent: session.agent_id,
          toSession: session.id,
        });
        setSelectedAgentId(session.agent_id);
      }
      setActiveSession(session.id);
    },
    [activeAgent, setSelectedAgentId, setActiveSession],
  );

  const handleProjectChange = useCallback(
    (projectId: string | null) => {
      if (projectId === activeProjectId) return;
      uiLogger.info("selectProjectContext", {
        from: activeProjectId,
        to: projectId,
        previousSessionId: activeSessionId,
      });
      const plan = planProjectContextChange({
        targetProjectId: projectId,
        activeSessionId,
        currentSession: currentSession ?? null,
      });
      switch (plan.kind) {
        case "awaitSession":
          return;
        case "detachCurrent":
          setSessionProject.mutate({ sessionId: plan.sessionId, projectId: null });
          break;
        case "startFreshChat":
          setSelectedAgentId(plan.agentId);
          setSelectedProjectId(plan.projectId);
          setActiveSession(null);
          break;
        case "setDraftProject":
          setSelectedProjectId(plan.projectId);
          break;
      }
      requestInputFocus();
    }, [
      activeProjectId,
      activeSessionId,
      currentSession,
      setSessionProject,
      setSelectedAgentId,
      setSelectedProjectId,
      setActiveSession,
      requestInputFocus,
    ],
  );

  // Archiving the chat currently in view would otherwise strand the
  // conversation pane on a now read-only, "dangling" session. Mirror the Inbox
  // list: advance selection to the next chat in the (sorted, non-archived)
  // history, fall back to the previous one, and clear only when nothing is
  // left. Routing the non-null advance through handleSelectSession keeps
  // selectedAgentId in sync, so a follow-up "new chat" still defaults to the
  // right agent even when the next chat belongs to a different agent. A no-op
  // when the archived session isn't the open one — that selection stays put.
  const advanceSelectionAfterArchive = useCallback(
    (session: { id: string; agent_id: string }) => {
      if (activeSessionId !== session.id) return;
      const history = sortChatSessions(
        sessions.filter((s) => s.status !== "archived"),
      );
      const idx = history.findIndex((s) => s.id === session.id);
      const next = history[idx + 1] ?? history[idx - 1] ?? null;
      if (next) handleSelectSession(next);
      else setActiveSession(null);
    },
    [activeSessionId, sessions, handleSelectSession, setActiveSession],
  );

  const archiveSession = useCallback(
    (sessionId: string) => setArchived.mutate({ sessionId, archived: true }),
    [setArchived],
  );

  const hasMessages = messages.length > 0 || !!pendingTaskId;

  return {
    // identity / lists
    wsId,
    user,
    agents,
    availableAgents,
    agentsSettled,
    sessions,
    projects,
    activeSessionId,
    selectedAgentId,
    activeProjectId,
    projectContextUnsupported: projectContextSupport === false,
    isProjectUpdating:
      setSessionProject.isPending || (!!activeSessionId && !currentSession),
    currentSession,
    isSessionArchived,
    isAgentArchived,
    isAgentAccessRevoked,
    isAgentRuntimeBound,
    activeAgent,
    noAgent,
    availability,
    // messages
    messages,
    pendingTask,
    pendingTaskLoading,
    pendingTaskId,
    showSkeleton,
    hasMessages,
    firstItemIndex,
    hasOlderMessages: !!hasOlderMessages,
    isFetchingOlderMessages,
    fetchOlderMessages,
    // draft restore
    restoreDraftRequest,
    handleRestoreDraftApplied,
    // compose-box focus nonce (bumped on new chat)
    focusInputRequest,
    conversationStarterRequest,
    handleConversationStarterApplied,
    sendConversationStarter,
    // actions
    handleSend,
    handleStop,
    handleSendQueuedTaskNow,
    handleEditQueuedTask,
    handleRemoveQueuedTask,
    handleClearQueuedTasks,
    uploadEnabled,
    handleNewChat,
    handleStartNewChat,
    handleSelectAgent,
    handleSelectSession,
    handleProjectChange,
    advanceSelectionAfterArchive,
    archiveSession,
    // store setters (for surfaces that sync selection to the URL, etc.)
    setActiveSession,
    setSelectedAgentId,
  };
}

export type ChatController = ReturnType<typeof useChatController>;

import { useCallback, useEffect, useRef, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { chatDraftRestoresOptions } from "@workpal/core/chat/queries";
import { useConsumeChatDraftRestore } from "@workpal/core/chat/mutations";
import { useChatStore } from "@workpal/core/chat";
import { removeChatMessageFromCaches } from "@workpal/core/realtime";
import type { Attachment } from "@workpal/core/types";

/**
 * A draft the composer is asked to adopt. Two sources feed it:
 * - a failed send, restoring the user's own text (no `serverRestoreId`);
 * - a durable deferred-cancellation restore (#5219), which has a server row.
 */
export interface RestoreDraftRequest {
  id: string;
  content: string;
  attachments?: Attachment[];
  /**
   * Draft slot this restore targets. The composer only applies it while the
   * user is viewing that session, so a restore never lands in the wrong chat.
   */
  sessionId?: string;
  /** Set for durable restores: the row to delete once the draft is applied. */
  serverRestoreId?: string;
}

/**
 * Owns draft restoration for the chat page and floating composer.
 * Durable cancellation restores remain on the server until applied. Failed-send
 * and synchronous-cancel restores have no server copy, so persist them per session
 * until the composer confirms application. The shared request slot exposes only
 * the visible session's next offer.
 *
 * Only visible composers participate. A nonempty draft defers the offer without
 * consuming it. Record application in a persisted ledger before sending consume;
 * retry consumption on later fetches and clear the ledger on server confirmation.
 * This ordering prevents a lost response from offering an already-applied prompt.
 *
 * Two visible clients may restore the same prompt locally; consumption is
 * idempotent. Apply before consume: claiming first could lose the only copy if
 * the winning client closes before writing its draft.
 */
export function useChatDraftRestore(activeSessionId: string | null, enabled = true) {
  const qc = useQueryClient();
  const [restoreDraftRequest, setRestoreDraftRequest] = useState<RestoreDraftRequest | null>(null);

  const appliedRestoreIds = useChatStore((s) => s.appliedDraftRestoreIds);
  const markDraftRestoreApplied = useChatStore((s) => s.markDraftRestoreApplied);
  const forgetDraftRestoreApplied = useChatStore((s) => s.forgetDraftRestoreApplied);
  const pendingSendRestores = useChatStore((s) => s.pendingSendRestores);
  const enqueuePendingSendRestore = useChatStore((s) => s.enqueuePendingSendRestore);
  const dequeuePendingSendRestore = useChatStore((s) => s.dequeuePendingSendRestore);
  const consumeDraftRestore = useConsumeChatDraftRestore();

  // The query refetches on composer mount and on network reconnect, and the
  // initiator's realtime handler invalidates it when chat:cancel_finalized
  // arrives — so a client that was offline across the broadcast still recovers
  // the prompt here. Disabled composers do not even fetch: no offer, no claim.
  const { data: draftRestoresData } = useQuery({
    ...chatDraftRestoresOptions(activeSessionId ?? ""),
    enabled: enabled && !!activeSessionId,
  });
  const restores = draftRestoresData?.restores;

  // In-flight consumes, so a re-render or a second fetch doesn't fire a duplicate
  // request for the same row. Released on settle — including on failure, which is
  // what lets the next fetch reconcile a consume whose retries all ran out.
  const reconcilingRef = useRef<Set<string>>(new Set());
  const consume = useCallback(
    (sessionId: string, restoreId: string) => {
      reconcilingRef.current.add(restoreId);
      consumeDraftRestore.mutate(
        { sessionId, restoreId },
        {
          // The row is gone: the ledger entry has nothing left to protect against.
          onSuccess: () => forgetDraftRestoreApplied(restoreId),
          onSettled: () => reconcilingRef.current.delete(restoreId),
        },
      );
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps -- mutation ref stable
    [forgetDraftRestoreApplied],
  );

  // Reconcile rows whose consume never landed. Firing this from the fetched list
  // (rather than only at apply time) is what closes the lost-consume hole: the
  // row is re-consumed on the next mount, refetch or reconnect until it is gone.
  useEffect(() => {
    if (!enabled || !activeSessionId || !restores) return;
    for (const r of restores) {
      if (r.chat_session_id !== activeSessionId) continue;
      if (!appliedRestoreIds.includes(r.id)) continue;
      if (reconcilingRef.current.has(r.id)) continue;
      consume(activeSessionId, r.id);
    }
  }, [restores, activeSessionId, appliedRestoreIds, consume, enabled]);

  useEffect(() => {
    if (!enabled) {
      // The composer went away (window closed, tab backgrounded). Release the
      // slot rather than hold an offer nobody can see: a durable request is
      // refetched, a server-less one is still in its persisted queue. Nothing was
      // applied, so nothing is lost, and the composer the user IS looking at —
      // here or on another device — gets to claim it.
      if (restoreDraftRequest) setRestoreDraftRequest(null);
      return;
    }
    if (!activeSessionId) return;
    if (restoreDraftRequest) {
      // One rule for the single slot: it only ever holds a request for the
      // session on screen. ChatInput treats a request it cannot apply as a WAIT,
      // so one aimed at a session the user may never return to would otherwise
      // starve every hand-off for the session they ARE looking at.
      //
      // Releasing it costs nothing either way: a durable request has a server row
      // and is offered again on the next fetch; a server-less one is still in
      // pendingSendRestores, queued against its own session, and is re-offered
      // when the user comes back to it.
      const { sessionId } = restoreDraftRequest;
      if (!sessionId || sessionId === activeSessionId) return;
      setRestoreDraftRequest(null);
      return;
    }
    // Server-less restores go first. Both kinds are re-offered until applied, but
    // this one is the user's own text with no copy anywhere else, so it is the
    // one to get in front of them soonest. It stays in the queue until ChatInput
    // reports the hand-off — a request that is merely offered can still be lost.
    const queued = pendingSendRestores[activeSessionId]?.[0];
    if (queued) {
      setRestoreDraftRequest({
        id: queued.id,
        content: queued.content,
        attachments: queued.attachments,
        sessionId: activeSessionId,
      });
      return;
    }
    const restore = restores?.find(
      (r) => r.chat_session_id === activeSessionId && !appliedRestoreIds.includes(r.id),
    );
    if (!restore) return;
    // If this client missed the chat:cancel_finalized event, the deleted bubble
    // may still sit in the message caches — drop it before restoring.
    removeChatMessageFromCaches(qc, activeSessionId, restore.id);
    setRestoreDraftRequest({
      id: restore.id,
      content: restore.content ?? "",
      attachments: restore.attachments,
      sessionId: activeSessionId,
      serverRestoreId: restore.id,
    });
  }, [
    restores,
    activeSessionId,
    restoreDraftRequest,
    appliedRestoreIds,
    pendingSendRestores,
    qc,
    enabled,
  ]);

  /**
   * A restore with no server copy — a failed send, or a cancel that answered
   * synchronously. It goes straight into the persisted per-session queue, never
   * into the shared slot: its text exists nowhere else, so it has to survive an
   * unmount, and it must not hold the slot hostage for a session the user is not
   * looking at. The effect above hands it to the composer when they are.
   */
  const enqueueLocalRestore = useCallback(
    (restore: { id: string; content: string; attachments?: Attachment[]; sessionId: string }) => {
      enqueuePendingSendRestore(restore);
    },
    [enqueuePendingSendRestore],
  );

  /**
   * The composer wrote the draft. This is the only terminal transition: for a
   * durable restore, record it in the ledger before consuming; for a server-less
   * one, drop the queue entry now that its text lives in the (persisted) draft.
   * A skipped hand-off never reaches here.
   */
  const handleRestoreDraftApplied = useCallback(() => {
    if (!restoreDraftRequest) return;
    const { id, serverRestoreId, sessionId } = restoreDraftRequest;
    if (serverRestoreId && sessionId) {
      markDraftRestoreApplied(serverRestoreId);
      consume(sessionId, serverRestoreId);
    } else if (sessionId) {
      dequeuePendingSendRestore(sessionId, id);
    }
    setRestoreDraftRequest(null);
  }, [restoreDraftRequest, markDraftRestoreApplied, consume, dequeuePendingSendRestore]);

  return { restoreDraftRequest, enqueueLocalRestore, handleRestoreDraftApplied };
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { api } from "../api";
import { useWorkspaceId } from "../hooks";
import { chatKeys, sortChatSessions, QUICK_ACTIONS_PENDING_TIMEOUT_MS } from "./queries";
import { createLogger } from "../logger";
import type {
  ChatSession,
  ChatPinnedAgent,
  ChatWakeup,
  ChatDraftRestoresResponse,
  ChatQuickActionsPendingState,
} from "../types";

const logger = createLogger("chat.mut");

/**
 * Consume a deferred-cancellation draft restore (#5219) after the composer has
 * applied it. The endpoint is idempotent, so consuming twice — or consuming a
 * row a previous attempt already deleted — is safe, which is what lets this
 * retry at all (mutations are `retry: false` app-wide).
 *
 * A lost consume must never re-restore a prompt the user has since sent, so the
 * "applied" decision is not carried by this request: the caller records it in
 * the persisted ledger (`markDraftRestoreApplied`) before firing, and reconciles
 * any row that outlives its ledger entry by consuming it again. This mutation
 * only has to make that reconciliation converge quickly.
 */
export function useConsumeChatDraftRestore() {
  const qc = useQueryClient();

  return useMutation({
    mutationFn: ({ sessionId, restoreId }: { sessionId: string; restoreId: string }) =>
      api.consumeChatDraftRestore(sessionId, restoreId),
    retry: 3,
    retryDelay: (attempt) => Math.min(1000 * 2 ** attempt, 8000),
    onMutate: ({ sessionId, restoreId }) => {
      qc.setQueryData<ChatDraftRestoresResponse>(
        chatKeys.draftRestores(sessionId),
        (old) =>
          old
            ? { ...old, restores: old.restores.filter((r) => r.id !== restoreId) }
            : old,
      );
    },
    onError: (err, { sessionId, restoreId }) => {
      // Exhausted the retries. The draft is safe (it is in the composer) and the
      // ledger keeps the row from being re-offered; the next mount reconciles it.
      logger.warn("consumeChatDraftRestore.error", { sessionId, restoreId, err });
    },
  });
}

/**
