      );
      return { prev };
    },
    onError: (err, { sessionId }, ctx) => {
      logger.warn("cancelChatWakeup.error", { sessionId, err });
      if (ctx?.prev) qc.setQueryData(chatKeys.wakeups(sessionId), ctx.prev);
